from urllib.parse import unquote_plus


def parse_query(qs: str) -> dict:
    result = {}
    hex_digits = set("0123456789abcdefABCDEF")

    def decode(component: str) -> str:
        for i, char in enumerate(component):
            if char == "%":
                if (
                    i + 2 >= len(component)
                    or component[i + 1] not in hex_digits
                    or component[i + 2] not in hex_digits
                ):
                    raise ValueError("malformed percent-escape")
        return unquote_plus(component, encoding="utf-8", errors="replace")

    for pair in qs.split("&"):
        if not pair:
            continue

        if "=" in pair:
            key, value = pair.split("=", 1)
        else:
            key, value = pair, ""

        decoded_key = decode(key)
        decoded_value = decode(value)
        result.setdefault(decoded_key, []).append(decoded_value)

    return result
